const KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote','work from anywhere',
  'remote data analyst','remote data scientist','remote ai marketing','remote marketing analyst',
  'remote growth analyst','remote bi analyst','remote automation specialist','remote ai workflow consultant'
];

const REJECT_PHRASES = [
  'us only','u.s. only','united states only','canada only','uk only','u.k. only','eu only',
  'europe only','australia only','must be based in','must live in',
  'must be authorized to work in','local work permit required','hybrid','onsite','on-site',
  'office required','remote within','fixed us hours','fixed eu hours'
];

const KEEP_PHRASES = [
  'worldwide remote','global remote','work from anywhere','anywhere','apac remote',
  'international contractors','contractor role','b2b contractor','hires via deel',
  'hires via remote.com','hires via oyster','eor supported','remote first','distributed team'
];

const ASYNC_KEEP_PHRASES = [
  'async','asynchronous','flexible hours','flexible schedule','distributed team',
  'remote first','low meeting culture','work across time zones'
];

const ASYNC_REJECT_PHRASES = [
  'strict 9 to 5','strict 9-5','fixed us hours','fixed est hours','fixed pst hours',
  'fixed cet hours','daily live calls required','must overlap full business day'
];

const ROLE_PRIMARY = [
  'data analyst','data scientist','junior data scientist','business intelligence analyst',
  'bi analyst','marketing analyst','performance marketing analyst','growth analyst',
  'ai marketing specialist','ai automation specialist','ai workflow consultant',
  'creative strategist','martech analyst'
];

return [{
  json: {
    KEYWORDS, REJECT_PHRASES, KEEP_PHRASES, ASYNC_KEEP_PHRASES, ASYNC_REJECT_PHRASES, ROLE_PRIMARY,
    runDate: new Date().toISOString().slice(0, 10)
  }
}];

const out = [];
for (const item of $input.all()) {
  const data = item.json;
  const arr = Array.isArray(data) ? data : [data];
  for (const j of arr) {
    if (!j || !j.id || j.legal) continue; // skip RemoteOK's legal notice row
    out.push({ json: {
      source: 'Remote OK',
      job_title: j.position || j.title || '',
      company: j.company || '',
      job_url: j.url || (j.id ? `https://remoteok.com/remote-jobs/${j.id}` : ''),
      location_text: j.location || 'Worldwide',
      salary: (j.salary_min && j.salary_max) ? `${j.salary_min}-${j.salary_max}` : (j.salary || ''),
      description: (j.description || '').replace(/<[^>]+>/g, ' ').slice(0, 6000),
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
    }});
  }
}
return out;

const data = $input.first().json;
const jobs = Array.isArray(data.jobs) ? data.jobs : [];
return jobs.map(j => ({ json: {
  source: 'Remotive',
  job_title: j.title || '',
  company: j.company_name || '',
  job_url: j.url || '',
  location_text: j.candidate_required_location || 'Worldwide',
  salary: j.salary || '',
  description: (j.description || '').replace(/<[^>]+>/g, ' ').slice(0, 6000),
  posted_date: j.publication_date || '',
  tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
}}));

const KEYWORDS = $('Config').first().json.KEYWORDS;
const runDate = $('Config').first().json.runDate;
const out = [];

function matchesKeyword(text) {
  const t = (text || '').toLowerCase();
  return KEYWORDS.some(k => t.includes(k));
}

function normRss(j) {
  const link = j.link || '';
  let source = 'Unknown Source';
  if (link.includes('weworkremotely.com')) source = 'We Work Remotely';
  else if (link.includes('himalayas.app')) source = 'Himalayas';
  return {
    source,
    job_title: j.title || '',
    company: (j.creator || (j.title || '').split(':')[0] || '').trim(),
    job_url: link,
    location_text: 'See listing',
    salary: '',
    description: (j.contentSnippet || j.content || '').slice(0, 6000),
    posted_date: j.isoDate || j.pubDate || '',
    tags: Array.isArray(j.categories) ? j.categories.join(', ') : ''
  };
}

for (const item of $input.all()) {
  const j = item.json;
  let job;
  if (j.source !== undefined && j.job_url !== undefined) {
    // already normalized by Flatten RemoteOK / Flatten Remotive
    job = { ...j };
  } else if (j.link !== undefined && j.title !== undefined) {
    // raw RSS item (We Work Remotely / Himalayas)
    job = normRss(j);
  } else {
    continue; // unrecognized shape (e.g. a disabled source), skip
  }
  if (!job.job_url || !job.job_title) continue;
  const haystack = `${job.job_title} ${job.description} ${job.tags}`;
  if (!matchesKeyword(haystack)) continue;
  job.date_found = runDate;
  job.job_id = Buffer.from(job.job_url).toString('base64').slice(0, 24);
  job._kind = 'new';
  out.push({ json: job });
}
return out;

const all = $input.all().map(i => i.json);
const existing = all.filter(j => j._kind === 'existing');
const incoming = all.filter(j => j._kind === 'new');

const existingUrls = new Set(existing.map(j => (j.job_url || '').trim().toLowerCase()).filter(Boolean));
const existingKeys = new Set(existing.map(j => `${(j.company || '').trim().toLowerCase()}|${(j.job_title || '').trim().toLowerCase()}`));

const seenThisRun = new Set();
const out = [];
for (const job of incoming) {
  const url = (job.job_url || '').trim().toLowerCase();
  const key = `${(job.company || '').trim().toLowerCase()}|${(job.job_title || '').trim().toLowerCase()}`;
  if (!url) continue;
  if (existingUrls.has(url) || existingKeys.has(key)) continue;
  if (seenThisRun.has(url) || seenThisRun.has(key)) continue;
  seenThisRun.add(url);
  seenThisRun.add(key);
  delete job._kind;
  out.push({ json: job });
}
return out;

const REJECT_PHRASES = $('Config').first().json.REJECT_PHRASES;
const KEEP_PHRASES = $('Config').first().json.KEEP_PHRASES;
const out = [];
for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.location_text} ${job.tags}`.toLowerCase();
  const rejectHit = REJECT_PHRASES.find(p => text.includes(p));
  const keepHit = KEEP_PHRASES.find(p => text.includes(p));
  let result, reason;
  if (rejectHit && !keepHit) {
    result = 'reject';
    reason = `Contains restrictive phrase: "${rejectHit}"`;
  } else if (rejectHit && keepHit) {
    result = 'pass'; // ambiguous (e.g. "no hybrid required") — let the AI eligibility check decide
    reason = `Ambiguous: has "${rejectHit}" but also "${keepHit}" — sent to AI check`;
  } else {
    result = 'pass';
    reason = keepHit ? `Contains welcoming phrase: "${keepHit}"` : 'No restriction phrases found';
  }
  out.push({ json: { ...job, hard_filter_result: result, hard_filter_reason: reason } });
}
return out;

const runDate = $('Config').first().json.runDate;
return $input.all().map(item => ({ json: {
  date_rejected: runDate,
  job_title: item.json.job_title,
  company: item.json.company,
  job_url: item.json.job_url,
  reason: item.json.hard_filter_reason,
  reject_stage: 'hard_filter'
}}));

const original = $('Hard Filter (Keyword Rules)').item.json;
const resp = $input.first().json;
let text = '';
try { text = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) { text = ''; }

let parsed = {
  taiwan_eligible: 'unclear',
  reason: 'AI response could not be parsed — flagged for manual check',
  location_risk: 'medium',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};
const match = text.match(/\{[\s\S]*\}/);
if (match) {
  try { parsed = JSON.parse(match[0]); } catch (e) { /* keep fallback */ }
}

return [{ json: {
  ...original,
  taiwan_eligible: parsed.taiwan_eligible,
  taiwan_reason: parsed.reason,
  location_risk: parsed.location_risk,
  timezone_risk: parsed.timezone_risk,
  contractor_possible: parsed.contractor_possible,
  ai_decision: parsed.decision
}}];

const ASYNC_KEEP = $('Config').first().json.ASYNC_KEEP_PHRASES;
const ASYNC_REJECT = $('Config').first().json.ASYNC_REJECT_PHRASES;
const job = $input.first().json;
const text = `${job.description} ${job.tags}`.toLowerCase();

const rejectHit = ASYNC_REJECT.find(p => text.includes(p));
const keepHits = ASYNC_KEEP.filter(p => text.includes(p));

let async_level;
if (rejectHit && keepHits.length === 0) async_level = 'low';
else if (keepHits.some(p => p.includes('async'))) async_level = 'high';
else if (keepHits.length > 0) async_level = 'medium';
else async_level = 'unclear';

return [{ json: { ...job, async_level, async_flags: keepHits.join(', '), async_reject_flag: rejectHit || '' } }];

const ROLE_PRIMARY = $('Config').first().json.ROLE_PRIMARY;
const job = $input.first().json;
const text = `${job.job_title} ${job.description} ${job.tags}`.toLowerCase();

const roleHit = ROLE_PRIMARY.find(r => text.includes(r));
const role_category = roleHit || (/\b(data|marketing|analytics|growth|automation|ai)\b/.test(text) ? 'adjacent role' : 'other');

const elig = (job.taiwan_eligible || '').toLowerCase();
const locRisk = (job.location_risk || '').toLowerCase();
const tzRisk = (job.timezone_risk || '').toLowerCase();

let taiwan_points = 0;
if (elig === 'yes' && /worldwide|anywhere|global|contractor/.test(text)) taiwan_points = 40;
else if (elig === 'yes' && /apac/.test(text)) taiwan_points = 30;
else if (elig === 'yes') taiwan_points = 20;
else if (elig === 'unclear' && locRisk !== 'high') taiwan_points = 20;
else taiwan_points = 0;

let async_points = 0;
if (job.async_level === 'high') async_points = 25;
else if (job.async_level === 'medium') async_points = 15;
else if (/distributed team/.test(text)) async_points = 15;
else if (/remote first/.test(text)) async_points = 10;

let role_points = 0;
if (roleHit) role_points = 25;
else if (role_category === 'adjacent role') role_points = 15;

let salary_points = 0;
const salaryText = (job.salary || '').toString();
const salaryNums = salaryText.match(/\d[\d,]{2,}/g);
let maxSalary = 0;
if (salaryNums) maxSalary = Math.max(...salaryNums.map(n => parseInt(n.replace(/,/g, ''), 10)));
if (maxSalary > 0) salary_points = 10;
if (maxSalary >= 3000) salary_points = 15;
if (maxSalary >= 5000) salary_points = 25;

let score = Math.min(taiwan_points + async_points + role_points + salary_points, 100);

let decision;
if (elig === 'yes' && score >= 85 && ['high', 'medium'].includes(job.async_level) && locRisk === 'low' && ['low', 'medium'].includes(tzRisk)) {
  decision = 'apply_now';
} else if (elig === 'unclear' && score >= 85 && locRisk === 'medium') {
  decision = 'manual_check';
} else if (elig === 'no' || locRisk === 'high' || tzRisk === 'high' || score < 70) {
  decision = 'reject';
} else {
  decision = 'manual_check';
}
// One-sentence rule hard gate: "I can do this job while living in Taiwan, without moving,
// without foreign work authorization, and without destroying my sleep schedule."
if (elig === 'no' || locRisk === 'high') decision = 'reject';

const whyParts = [];
if (taiwan_points >= 30) whyParts.push('Clearly worldwide/global/APAC-friendly for Taiwan');
if (async_points >= 15) whyParts.push(`${job.async_level} async fit`);
if (role_points >= 15) whyParts.push(`Matches role focus (${role_category})`);
if (salary_points >= 15) whyParts.push('Salary meets target range');
const why_good_fit = whyParts.join('; ') || 'Passed eligibility and role filters';

return [{ json: {
  ...job,
  role_category,
  score,
  score_breakdown: `taiwan:${taiwan_points} async:${async_points} role:${role_points} salary:${salary_points}`,
  why_good_fit,
  decision,
  application_status: decision === 'apply_now' ? 'ready_to_apply' : (decision === 'manual_check' ? 'needs_review' : 'not_applicable'),
  notes: ''
} }];

const runDate = $('Config').first().json.runDate;
const job = $input.first().json;
return [{ json: {
  date_rejected: runDate,
  job_title: job.job_title,
  company: job.company,
  job_url: job.job_url,
  reason: `Score ${job.score}/100, decision=${job.decision}, taiwan_eligible=${job.taiwan_eligible}, location_risk=${job.location_risk}, timezone_risk=${job.timezone_risk}`,
  reject_stage: 'scoring'
}}];

