const original = $('Append Filtered Jobs').item.json;
const resp = $input.first().json;
let text = '';
try { text = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) { text = ''; }
return [{ json: { ...original, cover_letter: text.trim() } }];

const runDate = $('Config').first().json.runDate;
const all = $input.all().map(i => i.json);

const filtered = all.filter(j => j.score !== undefined);
const rejected = all.filter(j => j.reject_stage !== undefined);

const applyNow = filtered.filter(j => j.decision === 'apply_now');
const manualCheck = filtered.filter(j => j.decision === 'manual_check').sort((a, b) => b.score - a.score);
const top = [...filtered].sort((a, b) => b.score - a.score).slice(0, 5);

function countReasons(re) {
  return rejected.filter(j => re.test((j.reason || '').toLowerCase())).length;
}
const rejUsOnly = countReasons(/us only/);
const rejEuOnly = countReasons(/eu only|europe only/);
const rejHybrid = countReasons(/hybrid|onsite|office required/);
const rejTimezone = countReasons(/fixed .* hours|timezone|overlap full business day/);

let msg = `Daily Taiwan Eligible Async Remote Jobs — ${runDate}\n\n`;
msg += 'Top jobs today:\n\n';
if (top.length === 0) msg += 'No jobs cleared the score-70 bar today.\n\n';
top.forEach((j, i) => {
  msg += `${i + 1}. ${j.job_title}\n`;
  msg += `Company: ${j.company}\n`;
  msg += `Score: ${j.score}\n`;
  msg += `Taiwan eligible: ${j.taiwan_eligible}\n`;
  msg += `Reason: ${j.taiwan_reason}\n`;
  msg += `Async level: ${j.async_level}\n`;
  msg += `Timezone risk: ${j.timezone_risk}\n`;
  msg += `Salary: ${j.salary || 'Not listed'}\n`;
  msg += `Why it fits Jerry: ${j.why_good_fit}\n`;
  msg += `Apply link: ${j.job_url}\n\n`;
});

msg += 'Manual check:\n';
if (manualCheck.length === 0) {
  msg += 'None today.\n\n';
} else {
  manualCheck.forEach(j => { msg += `- ${j.job_title} at ${j.company} (score ${j.score}) — ${j.job_url}\n`; });
  msg += '\n';
}

msg += 'Rejected summary:\n';
msg += `US only: ${rejUsOnly}\n`;
msg += `EU only: ${rejEuOnly}\n`;
msg += `Hybrid/onsite: ${rejHybrid}\n`;
msg += `Timezone risk: ${rejTimezone}\n`;
msg += `Total rejected: ${rejected.length}\n`;
msg += `Applied automatically: ${applyNow.length}\n`;

return [{ json: { digest_text: msg, digest_date: runDate, apply_now_count: applyNow.length, filtered_count: filtered.length, rejected_count: rejected.length } }];
